BY = "Beyin"
BS = "Beyin sapı ve beyincik"
OM = "Omurilik ve zarlar"
KS = "Kranial sinirler"
SS = "Spinal sinirler ve pleksuslar"
OT = "Otonom sinir sistemi"


def N(id, tr, la, en, summary, origin, course, motor, sensory, clinical=(), related=(), models=(), aliases=(), extra=(), sections=(), group=KS, region="head"):
    facts = [("Çıkış / köken", origin), ("Seyir", course)]
    if motor:
        facts.append(("Motor (efferent)", motor))
    if sensory:
        facts.append(("Duyusal (afferent)", sensory))
    facts += list(extra)
    return E(id, tr, la, en, group, region, summary, facts=facts, sections=sections, clinical=clinical, related=related, models=models, aliases=aliases)


